<style>
.pm-shell{--pm-ink:#15213c;--pm-muted:#71809e;--pm-line:rgba(128,145,180,.18);display:grid;gap:1.25rem}.dark .pm-shell{--pm-ink:#f4f7ff;--pm-muted:#96a3be;--pm-line:rgba(148,163,184,.13)}
.pm-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:2rem;padding:2rem;border:1px solid rgba(99,102,241,.22);border-radius:1.5rem;background:linear-gradient(125deg,#111a3c 0%,#24235d 54%,#49327d 100%);box-shadow:0 22px 55px rgba(31,30,78,.22);color:#fff}.pm-hero:before,.pm-hero:after{content:"";position:absolute;border-radius:999px;pointer-events:none}.pm-hero:before{width:18rem;height:18rem;right:-5rem;top:-9rem;background:rgba(251,191,36,.18)}.pm-hero:after{width:13rem;height:13rem;right:18%;bottom:-9rem;background:rgba(96,165,250,.17)}
.pm-hero-copy,.pm-health{position:relative;z-index:1}.pm-kicker{display:inline-flex;align-items:center;gap:.45rem;margin-bottom:.7rem;color:#fcd34d;font-size:.72rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.pm-kicker i{width:.5rem;height:.5rem;border-radius:99px;background:#fbbf24;box-shadow:0 0 0 5px rgba(251,191,36,.12)}.pm-hero h2{margin:0;font-size:clamp(1.45rem,2.5vw,2.15rem);font-weight:850;letter-spacing:-.035em}.pm-hero p{max-width:42rem;margin:.55rem 0 0;color:#cbd5e1;font-size:.9rem;line-height:1.7}.pm-health{display:flex;align-items:center;gap:.75rem;min-width:max-content;padding:.85rem 1rem;border:1px solid rgba(255,255,255,.14);border-radius:1rem;background:rgba(15,23,42,.28);backdrop-filter:blur(12px)}.pm-health-dot{width:.65rem;height:.65rem;border-radius:99px;background:#34d399;box-shadow:0 0 0 6px rgba(52,211,153,.12)}.pm-health small{display:block;color:#a9b4cb;font-size:.65rem}.pm-health strong{display:block;margin-top:.15rem;font-size:.8rem}
.pm-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.9rem}.pm-stat{position:relative;overflow:hidden;padding:1.15rem 1.2rem;border:1px solid var(--pm-line);border-radius:1.15rem;background:rgba(255,255,255,.82);box-shadow:0 12px 32px rgba(30,41,59,.055)}.dark .pm-stat{background:rgba(17,24,39,.62)}.pm-stat:after{content:"";position:absolute;width:4.5rem;height:4.5rem;right:-2rem;bottom:-2.4rem;border-radius:99px;background:var(--stat-color,#6366f1);opacity:.12}.pm-stat-label{color:var(--pm-muted);font-size:.72rem;font-weight:700}.pm-stat-value{display:block;margin-top:.45rem;color:var(--pm-ink);font-size:1.55rem;font-weight:850;letter-spacing:-.04em}.pm-stat-note{display:block;margin-top:.25rem;color:var(--pm-muted);font-size:.65rem}
.pm-toolbar{display:flex;align-items:center;gap:.7rem;padding:.75rem;border:1px solid var(--pm-line);border-radius:1.15rem;background:rgba(255,255,255,.72)}.dark .pm-toolbar{background:rgba(17,24,39,.52)}.pm-search{position:relative;flex:1}.pm-search svg{position:absolute;left:.85rem;top:50%;width:1rem;transform:translateY(-50%);color:var(--pm-muted)}.pm-input,.pm-select{height:2.65rem;border:1px solid var(--pm-line);border-radius:.8rem;background:rgba(248,250,252,.86);color:var(--pm-ink);font-size:.78rem;outline:none;transition:.2s}.dark .pm-input,.dark .pm-select{background:rgba(2,6,23,.46)}.pm-input{width:100%;padding:0 .9rem 0 2.5rem}.pm-select{min-width:10rem;padding:0 2rem 0 .85rem}.pm-input:focus,.pm-select:focus{border-color:#818cf8;box-shadow:0 0 0 3px rgba(99,102,241,.12)}
.pm-stream{display:grid;gap:.75rem}.pm-card{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:1rem;padding:1.05rem 1.15rem;border:1px solid var(--pm-line);border-radius:1.1rem;background:rgba(255,255,255,.8);box-shadow:0 8px 26px rgba(30,41,59,.045);transition:transform .18s,border-color .18s,box-shadow .18s}.dark .pm-card{background:rgba(17,24,39,.58)}.pm-card:hover{transform:translateY(-2px);border-color:rgba(99,102,241,.34);box-shadow:0 15px 35px rgba(30,41,59,.09)}.pm-icon{display:grid;place-items:center;width:2.7rem;height:2.7rem;border-radius:.85rem;background:linear-gradient(145deg,#eef2ff,#e0e7ff);color:#4f46e5}.dark .pm-icon{background:rgba(99,102,241,.14);color:#a5b4fc}.pm-icon svg{width:1.25rem;height:1.25rem}.pm-main{min-width:0}.pm-titleline{display:flex;align-items:center;flex-wrap:wrap;gap:.55rem}.pm-title{overflow:hidden;color:var(--pm-ink);font-size:.86rem;font-weight:800;text-overflow:ellipsis;white-space:nowrap}.pm-badge{display:inline-flex;align-items:center;gap:.3rem;padding:.25rem .55rem;border-radius:99px;font-size:.62rem;font-weight:800;text-transform:capitalize}.pm-badge:before{content:"";width:.34rem;height:.34rem;border-radius:99px;background:currentColor}.pm-badge--paid,.pm-badge--processed{color:#059669;background:rgba(16,185,129,.1)}.pm-badge--failed,.pm-badge--rejected{color:#dc2626;background:rgba(239,68,68,.1)}.pm-badge--pending,.pm-badge--received,.pm-badge--processing{color:#d97706;background:rgba(245,158,11,.12)}.pm-badge--refunded{color:#7c3aed;background:rgba(139,92,246,.11)}.pm-meta{display:flex;flex-wrap:wrap;gap:.35rem 1rem;margin-top:.45rem;color:var(--pm-muted);font-size:.68rem}.pm-meta span{display:inline-flex;align-items:center;gap:.3rem}.pm-meta b{color:var(--pm-ink);font-weight:650}.pm-side{text-align:right}.pm-amount{display:block;color:var(--pm-ink);font-size:.95rem;font-weight:850}.pm-date{display:block;margin-top:.3rem;color:var(--pm-muted);font-size:.65rem}.pm-error{grid-column:2/-1;margin-top:-.2rem;padding:.65rem .75rem;border-left:3px solid #ef4444;border-radius:.55rem;background:rgba(239,68,68,.06);color:#dc2626;font-size:.68rem;line-height:1.5}.pm-empty{display:grid;place-items:center;min-height:18rem;padding:2rem;border:1px dashed rgba(129,140,248,.35);border-radius:1.25rem;text-align:center}.pm-empty span{display:grid;place-items:center;width:4rem;height:4rem;margin:auto;border-radius:1.25rem;background:rgba(99,102,241,.1);color:#6366f1;font-size:1.6rem}.pm-empty h3{margin:1rem 0 .3rem;color:var(--pm-ink);font-weight:800}.pm-empty p{margin:0;color:var(--pm-muted);font-size:.78rem}.pm-pagination{padding-top:.35rem}
@media(max-width:900px){.pm-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.pm-hero{align-items:flex-start;flex-direction:column}.pm-health{align-self:flex-start}}@media(max-width:640px){.pm-hero{padding:1.4rem}.pm-toolbar{align-items:stretch;flex-direction:column}.pm-select{width:100%}.pm-card{grid-template-columns:auto minmax(0,1fr)}.pm-side{grid-column:2;text-align:left}.pm-error{grid-column:1/-1}.pm-stats{gap:.6rem}.pm-stat{padding:1rem}.pm-stat-value{font-size:1.25rem}}
</style>
